WITH flagged AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.merchant, s.is_flagged, s.is_new_session, CASE WHEN merchant RLIKE '^(Grab|Starbucks)$' THEN 'OTHER_ZONE' ELSE 'GROUP_A' END AS merchant_zone, (SELECT MAX(x.amount) FROM transactions x WHERE x.account_id = s.account_id) AS max_transaction_amount FROM sessions_transactions s ORDER BY max_transaction_amount DESC NULLS FIRST, merchant_zone
